import java.util.Scanner;

public class Main {

    // 计算在当前 n, m, d 下，F(a) 的最大值
    // 若不存在合法数组，返回 -1
    public static long getMaxF(long n, long m, long d) {
        // 只有一个数，没有相邻边
        if (n == 1) {
            return 0;
        }

        // 不允许相邻不同，整个数组必须相等
        if (d == 0) {
            if (m % n == 0) {
                return 0;
            }
            return -1;
        }

        // n == 2 时最多只有一条边
        if (n == 2) {
            return m;
        }

        // n >= 3
        if (d == 1) {
            return m;
        } else {
            return 2L * m;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        StringBuilder sb = new StringBuilder();

        int t = sc.nextInt();

        while (t-- > 0) {
            long n = sc.nextLong();
            long m = sc.nextLong();
            int q = sc.nextInt();

            while (q-- > 0) {
                long d = sc.nextLong();
                long y = sc.nextLong();

                long maxF = getMaxF(n, m, d);

                if (maxF != -1 && maxF >= y) {
                    sb.append("YES\n");
                } else {
                    sb.append("NO\n");
                }
            }
        }

        sc.close();
        System.out.print(sb.toString());
    }
}
```

